module async_fifo #(parameter WIDTH = 8, parameter DEPTH = 8)
  (input  wire             wclk,
   input  wire             wrst_n,
   input  wire             winc,
   input  wire [WIDTH-1:0] wdata,
   output wire             wfull,
   input  wire             rclk,
   input  wire             rrst_n,
   input  wire             rinc,
   output wire [WIDTH-1:0] rdata,
   output wire             rempty);

    localparam AW = $clog2(DEPTH);          // address bits
    localparam PW = AW + 1;                 // pointer bits (extra for full/empty)

    // ------------------------------------------------------------------
    // Memory
    // ------------------------------------------------------------------
    reg [WIDTH-1:0] mem [0:DEPTH-1];

    // ------------------------------------------------------------------
    // Binary and Gray pointers
    // ------------------------------------------------------------------
    reg [PW-1:0] wbin, rbin;
    reg [PW-1:0] wptr, rptr;                // Gray pointers, sent across domains
    wire [PW-1:0] wbin_next, rbin_next;
    wire [PW-1:0] wptr_next, rptr_next;

    assign wbin_next = wbin + (winc & ~wfull);
    assign wptr_next = (wbin_next >> 1) ^ wbin_next;

    assign rbin_next = rbin + (rinc & ~rempty);
    assign rptr_next = (rbin_next >> 1) ^ rbin_next;

    always @(posedge wclk or negedge wrst_n) begin
        if (!wrst_n) begin
            wbin <= {PW{1'b0}};
            wptr <= {PW{1'b0}};
        end else begin
            wbin <= wbin_next;
            wptr <= wptr_next;
        end
    end

    always @(posedge rclk or negedge rrst_n) begin
        if (!rrst_n) begin
            rbin <= {PW{1'b0}};
            rptr <= {PW{1'b0}};
        end else begin
            rbin <= rbin_next;
            rptr <= rptr_next;
        end
    end

    // ------------------------------------------------------------------
    // Synchronisers: wptr -> read domain, rptr -> write domain
    // ------------------------------------------------------------------
    reg [PW-1:0] wptr_sync1, wptr_sync2;    // wptr synced into rclk domain
    reg [PW-1:0] rptr_sync1, rptr_sync2;    // rptr synced into wclk domain

    always @(posedge rclk or negedge rrst_n) begin
        if (!rrst_n) begin
            wptr_sync1 <= {PW{1'b0}};
            wptr_sync2 <= {PW{1'b0}};
        end else begin
            wptr_sync1 <= wptr;
            wptr_sync2 <= wptr_sync1;
        end
    end

    always @(posedge wclk or negedge wrst_n) begin
        if (!wrst_n) begin
            rptr_sync1 <= {PW{1'b0}};
            rptr_sync2 <= {PW{1'b0}};
        end else begin
            rptr_sync1 <= rptr;
            rptr_sync2 <= rptr_sync1;
        end
    end

    // ------------------------------------------------------------------
    // Full / empty generation (in their own domains, from registered
    // pointers so there is no combinational loop through the pointer
    // next-state logic)
    // ------------------------------------------------------------------
    wire [AW-1:0] waddr = wbin[AW-1:0];
    wire [AW-1:0] raddr = rbin[AW-1:0];

    assign wfull  = (wptr == {~rptr_sync2[PW-1:PW-2], rptr_sync2[PW-3:0]});
    assign rempty = (rptr == wptr_sync2);

    // ------------------------------------------------------------------
    // Memory write / read
    // ------------------------------------------------------------------
    always @(posedge wclk) begin
        if (winc & ~wfull)
            mem[waddr] <= wdata;
    end

    assign rdata = mem[raddr];

endmodule
